SET TIME ZONE 'UTC';
WITH atual AS (SELECT date_trunc('month',p.data_pedido AT TIME ZONE 'America/Sao_Paulo')::date mes,p.canal_id,r.categoria_id,sum(v.receita_mercadoria_pos_devolucao) receita,sum(v.margem_mercadoria) margem,sum(v.quantidade) unidades FROM vw_itens_venda v JOIN pedidos p USING(pedido_id) JOIN produtos r USING(produto_id) WHERE v.elegivel GROUP BY 1,2,3), candidatos AS (SELECT a.*,b.receita receita_anterior,b.margem margem_anterior,b.unidades unidades_anteriores FROM atual a JOIN atual b ON b.canal_id=a.canal_id AND b.categoria_id=a.categoria_id AND b.mes=a.mes-interval '1 year' WHERE a.mes>=DATE '2024-01-01' AND a.unidades>0 AND b.unidades>0 AND a.receita<b.receita AND a.margem<b.margem) SELECT x.mes,c.codigo canal,ca.nome categoria,x.receita,x.receita_anterior,x.margem,x.margem_anterior,x.receita_anterior-x.receita queda_receita_abs,x.margem_anterior-x.margem queda_margem_abs,100*(x.receita_anterior-x.receita)/nullif(x.receita_anterior,0) queda_receita_pct,100*(x.margem_anterior-x.margem)/nullif(x.margem_anterior,0) queda_margem_pct,(x.receita_anterior-x.receita)+(x.margem_anterior-x.margem) score_investigacao FROM candidatos x JOIN canais c USING(canal_id) JOIN categorias ca USING(categoria_id) ORDER BY score_investigacao DESC,queda_receita_abs DESC,queda_margem_abs DESC,x.mes,c.codigo,ca.nome LIMIT 20;
